package org.slavicmyths.verify;
import java.util.*;import net.minecraft.world.level.levelgen.Heightmap;
import static org.slavicmyths.verify.Stabilization269.*;
/** Native exact-height microbenchmark; not server MSPT or whole-world generation timing. */
final class TerrainBench269 {
 static long[] column(int x,int z){long start=System.nanoTime();var column=w.getChunkSource().getGenerator().getBaseColumn(x,z,w,w.getChunkSource().randomState());int floor=w.getMinBuildHeight(),surface=floor;boolean found=false;for(int y=w.getMaxBuildHeight()-1;y>=w.getMinBuildHeight();y--){var state=column.getBlock(y);if(!found&&Heightmap.Types.WORLD_SURFACE_WG.isOpaque().test(state)){surface=y+1;found=true;}if(Heightmap.Types.OCEAN_FLOOR_WG.isOpaque().test(state)){floor=y+1;break;}}return new long[]{System.nanoTime()-start,floor,surface};}
 static long[] pair(int x,int z){long start=System.nanoTime();var generator=w.getChunkSource().getGenerator();int floor=generator.getBaseHeight(x,z,Heightmap.Types.OCEAN_FLOOR_WG,w,w.getChunkSource().randomState()),surface=generator.getBaseHeight(x,z,Heightmap.Types.WORLD_SURFACE_WG,w,w.getChunkSource().randomState());return new long[]{System.nanoTime()-start,floor,surface};}
 static void run(){current="native_exact_terrain_benchmark";for(int i=0;i<12;i++){column(1000+i*17,-2000+i*31);pair(1000+i*17,-2000+i*31);}var random=new Random(269);var col=new ArrayList<Long>();var pairs=new ArrayList<Long>();var points=new ArrayList<Map<String,Object>>();for(int i=0;i<192;i++){int x=random.nextInt(60001)-30000,z=random.nextInt(60001)-30000;long[] a,b;if(i%2==0){a=column(x,z);b=pair(x,z);}else{b=pair(x,z);a=column(x,z);}check(a[1]==b[1]&&a[2]==b[2],"exact native heightmap parity "+x+","+z);col.add(a[0]);pairs.add(b[0]);points.add(Map.of("x",x,"z",z,"floor",a[1],"surface",a[2],"full_column_ns",a[0],"two_height_queries_ns",b[0]));}out.put("terrain_samples",points);out.put("column_total_ms",col.stream().mapToLong(Long::longValue).sum()/1e6);out.put("pair_total_ms",pairs.stream().mapToLong(Long::longValue).sum()/1e6);Collections.sort(col);Collections.sort(pairs);out.put("column_p95_ms",col.get(182)/1e6);out.put("pair_p95_ms",pairs.get(182)/1e6);out.put("benchmark_scope","same real noise generator/seed, alternating order,12warmup,192unique columns; not measured worldgen speedup");}
}
